public void testSeparatorUsedInINIInput() throws Exception {
    final String inputSeparator = "=";
    final String input = "[section]" + LINE_SEPARATOR + "k1:v1$key1=value1" + LINE_SEPARATOR + "k1:v1,k2:v2$key2=value2" + LINE_SEPARATOR + "key3:value3" + LINE_SEPARATOR + "key4 = value4" + LINE_SEPARATOR;
    final INIConfiguration instance = new FileBasedConfigurationBuilder<>(INIConfiguration.class).configure(new Parameters().ini().setSeparatorUsedInInput(inputSeparator)).getConfiguration();
    load(instance, input);
    assertEquals("value1", instance.getString("section.k1:v1$key1"));
    assertEquals("value2", instance.getString("section.k1:v1,k2:v2$key2"));
    assertEquals("", instance.getString("section.key3:value3"));
